The classical problem in {\bf CS } is solving an under-determined linear system of equations
\begin{equation}
\mathcal{A} \textbf{v} = \textbf{b}
\label{eq:cs_classic}
\end{equation}
where $\textbf{v}=(v_1,...,v_N)$ is the vector of unknown variables, $\mathcal{A}$ is the {\it sensing} matrix, often called also the {\it mixing} matrix
and $\textbf{b}=(b_1,...,b_k)$ are the measured values of the $k$ equations.

\begin{equation}
\mathcal{A} \textbf{v} = \textbf{b}
\label{eq:cs_classic}
\end{equation}

We represent the results of the mixture Sanger sequencing
of length $k$ as a $4 \times k$ Position-specific-Score-Matrix (PSSM)
\begin{equation}
P =
\begin{pmatrix}
a_1 & a_2 & \cdots & a_k \\
c_1 & c_2 & \cdots & c_k \\
g_1 & g_2 & \cdots & g_k \\
t_1 & t_2 & \cdots & t_k \\
\end{pmatrix} =
\begin{pmatrix}
{\textbf a} \\
{\textbf c} \\
{\textbf g} \\
{\textbf t} \\
\end{pmatrix}
\label{eq:PSSM}
\end{equation}
where ${\textbf p}_j=(a_j, c_j, g_j, t_j)^t$ is a column vector representing the observed frequencies at sequence position $j$ of
the four nucleotides, with $a_j,c_j,g_j,t_j \geq 0$.

\begin{equation}
P =
\begin{pmatrix}
a_1 & a_2 & \cdots & a_k \\
c_1 & c_2 & \cdots & c_k \\
g_1 & g_2 & \cdots & g_k \\
t_1 & t_2 & \cdots & t_k \\
\end{pmatrix} =
\begin{pmatrix}
{\textbf a} \\
{\textbf c} \\
{\textbf g} \\
{\textbf t} \\
\end{pmatrix}
\label{eq:PSSM}
\end{equation}

\begin{equation}
\sum_{i=1}^N v_i 1_{\{ S_{ij} =  '\!A' \}} = a_j
\end{equation}

Define the $k \times N$ mixture matrix $A$ for the nucleotide '${A}$':
\begin{equation}
A_{ij}=\left\{ \begin{array}{ll}
1 & S_{ij} = '\!\!{A}' \\
0 & \mbox{otherwise} \end{array} \right.
\label{eq:MixMatrix}
\end{equation}
and similarly for the nucleotides $'\!{C}','\!{G}','\!{T}'$.

\begin{equation}
A_{ij}=\left\{ \begin{array}{ll}
1 & S_{ij} = '\!\!{A}' \\
0 & \mbox{otherwise} \end{array} \right.
\label{eq:MixMatrix}
\end{equation}

The constraints given by the sequencing reaction can therefore be expressed as:
\begin{equation}
A\textbf{v}=\textbf{a}, C\textbf{v}=\textbf{c}, G\textbf{v}=\textbf{g}, T\textbf{v}=\textbf{t} \label{eq:LinConstraints}
\end{equation}

\begin{equation}
A\textbf{v}=\textbf{a}, C\textbf{v}=\textbf{c}, G\textbf{v}=\textbf{g}, T\textbf{v}=\textbf{t} \label{eq:LinConstraints}
\end{equation}

In the {\bf CS } paradigm, one can formulate the quest for
the sparsest solution satisfying the given set of linear constraints as follows:
\begin{equation}
\textbf{v}^*= \underset{\textbf{v}}{argmin}\|\textbf{v}\|_{\ell 0} \quad s.t.
\quad A\textbf{v}=\textbf{a}, C\textbf{v}=\textbf{c}, G\textbf{v}=\textbf{g}, T\textbf{v}=\textbf{t}
\label{eq:L0Min}
\end{equation}

\begin{equation}
\textbf{v}^*= \underset{\textbf{v}}{argmin}\|\textbf{v}\|_{\ell 0} \quad s.t.
\quad A\textbf{v}=\textbf{a}, C\textbf{v}=\textbf{c}, G\textbf{v}=\textbf{g}, T\textbf{v}=\textbf{t}
\label{eq:L0Min}
\end{equation}

However, a remarkable breakthrough of the {\bf CS } theory shows that under certain conditions on
the mixture matrix and the number of measurements (see below), the sparse solution can be recovered uniquely by solving a convex relaxation
of the problem, which is obtained by replacing the $\ell 0$ norm with the ''closest'' convex $\ell p$ norm, namely the $\ell 1$ norm,
leading to the following minimization problem \cite{candes2006near,donoho2006most,tropp_just_2006}:
\begin{equation}
\textbf{v}^*=\underset{\textbf{v}}{argmin}\|\textbf{v}\|_{\ell 1} = \underset{\textbf{v}}{argmin}\sum_{i=1}^N |v_i| \quad s.t.
\quad A\textbf{v}=\textbf{a}, C\textbf{v}=\textbf{c}, G\textbf{v}=\textbf{g}, T\textbf{v}=\textbf{t}
\label{eq:L1Min}
\end{equation}
which is a convex optimization problem whose solution can be obtained in polynomial time.

\begin{equation}
\textbf{v}^*=\underset{\textbf{v}}{argmin}\|\textbf{v}\|_{\ell 1} = \underset{\textbf{v}}{argmin}\sum_{i=1}^N |v_i| \quad s.t.
\quad A\textbf{v}=\textbf{a}, C\textbf{v}=\textbf{c}, G\textbf{v}=\textbf{g}, T\textbf{v}=\textbf{t}
\label{eq:L1Min}
\end{equation}

\begin{equation}
\textbf{v}^* = \underset{\textbf{v}}{argmin} \:\: \frac{1}{2} \big( \|{\textbf a}-A\textbf{v}\|^2_{\ell 2} + \|{\textbf c}-C\textbf{v}\|^2_{\ell 2} +
\|{\textbf g}-G\textbf{v}\|^2_{\ell 2} + \|{\textbf t}-T\textbf{v}\|^2_{\ell 2} \big) + \tau \|\textbf{v}\|_{\ell 1}
\label{eq:GPSR}
\end{equation}

